package com.gameaggregator.buildservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="game_builds") public class GameBuild{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID versionId;@Column(nullable=false)public UUID uploadedBy;@Lob @Column(nullable=false)public String metadataJson;@Column(nullable=false)public String status="PENDING";public String artifactKey;public String checksumSha256;public long fileSize;public String contentType;@Column(nullable=false)public Instant createdAt=Instant.now();@Version public long revision;protected GameBuild(){}public GameBuild(UUID v,UUID u,String m){versionId=v;uploadedBy=u;metadataJson=m;}}